var n=`0557-machboos-laham`;var o=`world-0557`;var t=`KW`;var a=`western-asia`;var r=4;var s=104;var l={en:`Machboos Laham`,ua:`Мачбус із бараниною`};var m={en:`A traditional dish from Kuwait, centered on lamb, yellow onion, tomato, basmati rice. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Кувейт. Основні складники: ягнятина, жовта цибуля, помідор, рис басматі. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 14 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 14 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:14,i:[[`lamb`,820,`g`],[`yellow-onion`,210,`g`],[`sunflower-oil`,55,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 60 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 60 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:60,i:[[`tomato`,330,`g`],[`ground-cardamom`,5,`g`],[`ground-cinnamon`,4,`g`],[`water`,1050,`ml`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 27 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 27 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:27,i:[[`basmati-rice`,480,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`raisin`,80,`g`],[`almond`,60,`g`]]}];var g={slug:n,id:o,country:`KW`,region:a,servings:4,minutes:104,title:l,text:m,steps:d};export{t as country,g as default,o as id,s as minutes,a as region,r as servings,n as slug,d as steps,m as text,l as title};